using System;using System.IO;using SargasPC;
class FeedAccessTests {
 static int n;static void C(bool b){if(!b)throw new Exception("feed access check "+n);n++;}
 static void Main(){C(FeedAccessPolicy.Evaluate(null)==FeedAccessState.Missing);C(FeedAccessPolicy.Evaluate("")==FeedAccessState.Missing);C(FeedAccessPolicy.Evaluate("token-only-fixture")==FeedAccessState.Stored);C(FeedAccessPolicy.Evaluate("x\r\ny")==FeedAccessState.Invalid);C(FeedAccessPolicy.Evaluate("has space")==FeedAccessState.Invalid);C(FeedAccessPolicy.Evaluate(new string('x',513))==FeedAccessState.Invalid);C(FeedAccessPolicy.Explain(FeedAccessState.Stored).Contains("dar nepatvirtintas"));C(FeedAccessPolicy.NetworkError(true,401).Contains("Auth-Key"));C(FeedAccessPolicy.NetworkError(true,403).Contains("teises"));C(!FeedAccessPolicy.NetworkError(false,403).Contains("MalwareBazaar"));C(FeedAccessPolicy.NetworkError(true,429).Contains("pasiekiamumą"));C(FeedAccessPolicy.ResponseError("illegal_auth_key").Contains("atmetė"));C(!FeedAccessPolicy.ResponseError("server-secret-fixture").Contains("server-secret-fixture"));
 string root=Path.Combine(Path.GetTempPath(),"sargon-feed43-"+Guid.NewGuid());Directory.CreateDirectory(root);try{var c=new Core(root);C(c.FeedAccess()==FeedAccessState.Missing);string before=c.Database().Count.ToString();bool refused=false;try{c.UpdateFeed();}catch(IOException e){refused=e.Message.Contains("Auth-Key")&&e.Message.Contains("ClamAV");}C(refused);C(before==c.Database().Count.ToString()&&c.Config.FeedAt==0);File.WriteAllText(Path.Combine(root,"keys.dpapi"),"corrupt-not-a-key");C(c.FeedAccess()==FeedAccessState.Unreadable);refused=false;try{c.RequireFeedKey();}catch(IOException e){refused=e.Message.Contains("abu ryšio raktus")&&!e.Message.Contains("corrupt-not-a-key");}C(refused);C(File.ReadAllText(Path.Combine(root,"keys.dpapi"))=="corrupt-not-a-key");}finally{Directory.Delete(root,true);}Console.WriteLine("PASS: "+n+" feed access checks (missing/invalid/unreadable keys, no network without key, unchanged database, scoped authentication failures and no secret echo).");}
}
